package dev.hyperears.hook

import android.content.res.Resources
import android.graphics.BitmapFactory
import android.graphics.drawable.BitmapDrawable
import android.util.Base64

/**
 * Transparent Honor X5s Pro product icon embedded as base64.
 *
 * The image is injected into the MiLink process by drawable byte array; embedding avoids relying
 * on cross-process resource IDs or host AssetManager access.
 */
internal object HonorX5sHeadsetIcon {
    fun drawable(resources: Resources): BitmapDrawable? =
        runCatching {
            val bytes = Base64.decode(IMAGE_BASE64, Base64.DEFAULT)
            BitmapDrawable(resources, BitmapFactory.decodeByteArray(bytes, 0, bytes.size))
        }.getOrNull()

    private val IMAGE_BASE64 =
        ""
}
